{
  "agent": {
    "adapter": "claude-agent-acp",
    "name": "@agentclientprotocol/claude-agent-acp",
    "protocolVersion": 1,
    "version": "0.76.0"
  },
  "model": "claude-sonnet-5",
  "pid": 74202,
  "provider": "claude",
  "transport": "acp"
}

{
  "acpSessionId": "a7907580-23a0-4922-b4a8-426284f39bec",
  "provider": "claude",
  "sessionId": "a7907580-23a0-4922-b4a8-426284f39bec",
  "transport": "acp"
}

{
  "availableCommands": [
    {
      "description": "Build an animation from scratch, making the decisions in the order that determines whether it feels right — should it animate at all, what purpose, which tool, which properties, which curve and duration, how it interrupts, how it exits. Writes the implementation. Use when asked to animate something, add motion, make a component feel alive, or build a transition. For critiquing existing motion use review-animations; for auditing a whole codebase use improve-animations. (user)",
      "name": "animate"
    },
    {
      "description": "Apple's approach to interface design and fluid, physical motion, translated for the web. Use when building or reviewing gesture-driven UI, spring animations, drag/swipe/sheet interactions, momentum and interruptible transitions, translucent materials and depth, typography (optical sizing, tracking, leading), reduced-motion, or the design foundations (feedback, spatial consistency, restraint) behind Apple-style interfaces. (user)",
      "name": "apple-design"
    },
    {
      "description": "Turn a feature, fix, or ticket into a confirmed dependency graph of Oga tasks — grill the idea until it is executable, send one recon task to map the code, split the work into independently runnable tasks, pick each task's skill and difficulty, map the true dependency edges, confirm the map with the user, then dispatch every task in one pass with `dependsOn` wiring. Pass `--strict` to give every writing task independent reviewers in fresh contexts and a fixer that is not the writer. Use this skill whenever the user wants to ship a feature, shape a ticket into work, break something into parallel tasks, or scope and execute a change end to end. (user)",
      "input": {
        "hint": "[--strict] [idea|source-file|issue-id]"
      },
      "name": "build"
    },
    {
      "description": "Upgrade a project to Bun 1.4 (or later) safely, step by step — pin every place the version lives, fix the breaking changes, re-verify against a recorded baseline, then offer the new capabilities as an explicit opt-in menu. Use this skill when the user asks to upgrade Bun, move to Bun 1.4, adopt new Bun features, replace Playwright/Puppeteer with Bun.WebView, drop a dependency in favor of a Bun built-in, or when `bun install`/`bun test` starts behaving differently after a version bump. (user)",
      "name": "bun-upgrade"
    },
    {
      "description": "Verify a claim with fresh local evidence: restate it falsifiably, capture baseline and treatment, compare artifacts, and return VERIFIED, NOT VERIFIED, or INCONCLUSIVE. Use this skill when the user types `/check`, or asks 'verify this', 'prove it works', 'did this fix it', 'show me the evidence', or when a bug fix, UI, CLI, API, performance, or memory claim needs measured before/after proof. (user)",
      "name": "check"
    },
    {
      "description": "Co-author researched, opinionated long-form essays and articles with the user. Use when the user wants to develop substantial long-form content through source handling, author perspective, structure, drafting, and revision. Interview when key perspective or evidence is missing; draft directly when supplied material is already sufficient. Use the user's or publication's voice by default, with Cameroonian voice only when requested or present in source material. (user)",
      "name": "co-author"
    },
    {
      "description": "Optimize SQL databases, queries, indexes, schemas, and engine-specific performance issues for measurable gains. Use this skill whenever the user mentions slow queries, EXPLAIN or query plans, indexes, pagination, N+1 queries, DB bottlenecks, SQLite tuning or \"database is locked\" errors, PostgreSQL/MySQL tuning, connection pools, vacuum/analyze, WAL mode, InnoDB, JSON/JSONB, full-text search, or database performance reviews. Do not use it for broad app slowness or database selection unless SQL performance or concurrency requirements are the actual decision. (user)",
      "input": {
        "hint": "[query|schema|EXPLAIN output|slow path]"
      },
      "name": "db"
    },
    {
      "description": "Expert guidance for mobile client-integrity systems: Android hardware-backed keys and Key Attestation, StrongBox, TEE, Play Integrity API, iOS App Attest and DeviceCheck, request signing, canonical JSON, replay protection, certificate pinning, CRL checks, and Flutter platform-channel implementation. Use this skill whenever the user asks how to prove API requests come from a legitimate app and device, verify mobile client integrity, sign requests with hardware-bound keys, compare Play Integrity vs raw attestation, implement App Attest, prevent replay attacks, or add these patterns to a Flutter app. This is not a broad mobile security skill; it covers device-app-request integrity for backend verification. (user)",
      "name": "device-attest"
    },
    {
      "description": "Optimize Dockerfiles for smaller images, faster builds, and better runtime hygiene. Use this skill whenever the user asks to reduce image size, improve build caching, add multi-stage builds, harden container security, add healthchecks, fix slow CI builds, fix \"exec format error\" or multi-arch issues, handle CVE scan failures on images, or clean up Dockerfile and `.dockerignore` patterns — even if they only say the image is too big or builds are slow. (user)",
      "name": "docker"
    },
    {
      "description": "Generate a cohesive set of transparent-background icons in a chosen or brand-matched visual style. Use when the user wants custom icons, an icon pack / set, system icons, spot / feature / category icons, or icons matching a specific look (line, filled, colorblock, cartoon, isometric, 3D, sticker, realistic, animal badge) or a project's own design tokens. Renders 4x4 sheets via image generation on a flat grey backdrop, then slices and removes backgrounds into clean PNGs. Not for a single one-off icon (draw SVG instead) or dense 16-24px functional UI glyphs (use a vector icon library there). (user)",
      "name": "icon"
    },
    {
      "description": "Survey a codebase's animation and motion code as a senior motion advisor, then produce a prioritized audit and self-contained implementation plans for other agents (or cheaper models) to execute. Read-only on source code — it plans improvements, it does not apply them. Use when the user asks to \"improve the animations\", \"audit the motion\", \"make this app feel better\", or wants a roadmap of animation fixes rather than a review of a single diff. (user)",
      "name": "improve-animations"
    },
    {
      "description": "Install, configure, update, or upgrade vendored anti-slop Oxlint plugins. Use when adding anti-slop, picking up upstream rules or fixes, or migrating an existing installation while preserving local customizations. (user)",
      "name": "install-anti-slop"
    },
    {
      "description": "The house review bar for these codebases, applied before review instead of after. Two modes — `grill` (default: interrogate a plan or approach BEFORE implementation, then produce the short list of questions only the product owner can answer) and `apply` (judge finished work against the recorded rules). Both end with fewer review rounds because the objections were handled first. Use before starting any non-trivial feature, and before opening a PR. (user)",
      "input": {
        "hint": "[grill|apply] [target]"
      },
      "name": "isern"
    },
    {
      "description": "Build launch content plans for digital products as one copy-paste-ready CSV. Use this skill whenever the user wants launch posts, social content, email content, blog launch content, Product Hunt launch copy, community posts, or a launch calendar for a SaaS, app, course, template, API, newsletter, community, service, or similar offer. Output actual written content, not ideas. Default artifact is only `content-plan.csv` with Platform, Content, Date, and Topic columns. (user)",
      "name": "launch"
    },
    {
      "description": "Build Livewire v4 components using SFC defaults, client-side-first UI state, and idiomatic Laravel Livewire conventions. Use this skill for Livewire component mechanics, actions, forms, validation, events, binding, Alpine bridges, navigation, security, or tests. Pair it with UI design or semantic-HTML skills when visual or markup concerns dominate. (user)",
      "name": "livewire"
    },
    {
      "description": "Apply a named visual system to an interface — the aesthetic direction, not the engineering. The style is an arg so only that rule set loads; `scandinavian` and `neo-brutalism` ship today. Use when the user invokes /look, names a look (Scandinavian/Nordic/minimalist, neo-brutalist/neubrutalism), asks to restyle or redesign a surface's visual language, asks for a design direction, or wants a review of whether a page holds one coherent style. Pair with `ui` for accessibility, performance, states, and code standards, and `ux` for whether the task can be completed at all. (user)",
      "input": {
        "hint": "[style] [apply|review|prototype|deep] [target]"
      },
      "name": "look"
    },
    {
      "description": "Malico's intent harness. Grill the ask until it is executable by a stranger, do the small work here, dispatch anything with volume or open discovery to Oga, track results in the project ledger. This session holds intent and judgment first; it makes small self-contained changes itself and sends out the rest. Use it for every non-trivial ask in Malico's projects, and stay in it across long multi-project sessions. (user)",
      "input": {
        "hint": "[the ask]"
      },
      "name": "malico"
    },
    {
      "description": "Generate or audit HTML for WHATWG conformance, semantic element choice, form structure, and markup accessibility. Use for explicit semantic HTML, spec-compliance, markup-audit, or assistive-technology requests. Pair with UI or framework skills when visual design or component mechanics dominate; do not trigger for every frontend template change. (user)",
      "name": "markup"
    },
    {
      "description": "Design, implement, optimize, and explain interactive web animations driven by scroll, pointer, drag, touch, device orientation, data, or component state. Use when a webpage needs responsive visual motion for products, interfaces, diagrams, characters, or scene transitions. (user)",
      "name": "motion"
    },
    {
      "description": "Rewrite prompts into clear, structured instructions for AI systems. Use this skill whenever the user asks to improve a prompt, create a reusable prompt template, add guardrails, standardize output format, reduce hallucination, make model output more reliable, or turn messy notes into reusable instructions for an AI workflow. (user)",
      "name": "prompt"
    },
    {
      "description": "Build throwaway code that answers one design question — an interactive terminal app to pressure-test a state model, or several radically different UI variants switchable on one route. Use this skill whenever the user wants to sanity-check whether logic or a data shape feels right, explore what a screen should look like, compare layout options, or try an idea before committing it to production code. (user)",
      "input": {
        "hint": "<design question>"
      },
      "name": "prototype"
    },
    {
      "description": "Find Reddit threads where people are genuinely asking for what you offer, then draft short, genuinely helpful replies — disclosing your affiliation honestly and naming your product only when it truly answers the question. Two moves: discovery — scan the right subreddits for real needs (recommendation asks, expressed pain, competitor mentions) and rank the few threads where you can actually help; drafting — write from real experience, respect each community's self-promo rules, and keep a human in the loop to review and post. This markets on Reddit the honest way: contribute value, disclose who you are, never astroturf. Distilled from the playbook behind doany.ai's Reddit agent. Triggers on \"find reddit opportunities\", \"reddit marketing\", \"reddit automation\", \"reply on reddit for my product\", \"reddit community engagement\", \"reddit lead gen\", or any ask to turn Reddit threads into genuine, disclosed marketing replies. (user)",
      "name": "reddit-automation"
    },
    {
      "description": "Improve, review, refactor, or architect code for maintainability without adding slop. Five modes, passed as an arg so only that rule set loads — deslop (strip AI clutter from a diff), clean (behavior-preserving restructure), review (quality findings on a diff or PR), arch (module boundaries, migration), naming (naming grammar, API shape, structure, and documentation voice — for writing new code or judging a diff). Triggers on any ask to improve, tidy, simplify, or rename existing code, and on naming or API-shape questions, even without the word refactor. Run the full check — `/refactor` with no mode arg — as the finishing pass after any task that wrote code, covering deslop, structure, naming, and boundaries on that diff, including stripping comments that narrate a bug, fix, or ticket instead of describing the code. Prefer this for general code quality; leave database, Docker, UI, HTML, security, and framework work to their own skills. (user)",
      "input": {
        "hint": "[deslop|clean|review|arch|naming] [target]"
      },
      "name": "refactor"
    },
    {
      "description": "Draft concise platform-specific reports from messy debugging notes, incidents, status updates, investigation findings, or handoff context. Use this skill whenever the user types `/report`, asks for paste-ready copy for Slack, Telegram, email, docs, Linear, or GitHub, or asks for short vs long versions for different audiences. Especially use it when the same technical facts need different tone, length, and structure by platform. This skill drafts text; it does not send or publish it. (user)",
      "input": {
        "hint": "<telegram|slack|email|docs|linear|github>"
      },
      "name": "report"
    },
    {
      "description": "Investigate a question against high-trust primary sources and capture the findings as a cited Markdown file in the repo, led by a TL;DR. Use this skill when the user asks to research a topic, gather docs or API facts, compare libraries or approaches, check how something actually behaves upstream, or delegate reading legwork to a background agent. (user)",
      "name": "research"
    },
    {
      "description": "Reviews animation and motion code against a high craft bar derived from Emil Kowalski's design engineering philosophy. Default to flagging; approval is earned. (user)",
      "name": "review-animations"
    },
    {
      "description": "Rust data layout and allocation for types that exist in the millions. Use when asked why a type is so large, or on `size_of`, enum padding, `Vec` vs `Box<[T]>`, per-entry footprint, or allocator waste. (user)",
      "input": {
        "hint": "[audit|apply] [target]"
      },
      "name": "rust"
    },
    {
      "description": "Make a Tauri desktop app feel native rather than like a website in a window — window chrome, title bars, vibrancy, menus, keyboard shortcuts, scroll and selection behaviour, theme sync, and the platform differences between macOS, Windows, and Linux. Use when the user invokes /tauri, is building or polishing a Tauri app, or says their Tauri app \"feels like a web page\" — any of the behaviours above reading as browser rather than desktop. Tauri v2 only. Pair with `ui` for accessibility and states, and `look` for the visual system. (user)",
      "input": {
        "hint": "[audit|apply] [target]"
      },
      "name": "tauri"
    },
    {
      "description": "Teach a topic across multiple sessions in a persistent learning workspace — mission, resources, lessons, reference sheets, and learning records. Use this skill whenever the user asks to be taught something, wants to learn a topic or skill properly, asks for a course or curriculum, requests a lesson or practice drill, or resumes learning already started in this directory. (user)",
      "input": {
        "hint": "<what to learn>"
      },
      "name": "teach"
    },
    {
      "description": "Build frontend interfaces and UI components that are accessible, resilient, and fast on real devices. Use this skill for UI construction, styling, responsive layout, interaction polish, or UI-focused refactoring. The visual system and aesthetic direction live in `look` — pair the two whenever the work has a look to get right. Pair it with framework, semantic-HTML, or performance skills when those concerns dominate; do not use it alone for framework mechanics, markup-only audits, or performance diagnosis. (user)",
      "name": "ui"
    },
    {
      "description": "Diagnose whether people can understand and complete a task, and write the interface copy that makes it clear. Two modes. Diagnose: page or flow UX audit, friction or dead-end analysis, onboarding/checkout/forms/settings review, loading-empty-error-success state review, Apple-like clarity. Write: labels, helper text, empty states, error messages, onboarding copy, settings text, confirmation dialogs, product language cleanup, tone consistency, microcopy. Apply the target platform's conventions; do not copy Apple visuals onto web, Android, or other platforms. Diagnosis is read-only — not visual styling, implementation, compliance auditing, or performance tracing. (user)",
      "input": {
        "hint": "[diagnose|write]"
      },
      "name": "ux"
    },
    {
      "description": "Create raster illustrations in one consistent manga-ink visual system, in two modes — finished explainer images with short English labels rendered inside the scene, and transparent character illustrations cut out with a bundled background-removal script. Use for concept and mechanism explainers, comparisons, workflows, tradeoffs, feedback loops, pipeline diagrams, hero art, README and slide illustrations, blog headers, and reusable character scenes with the glasses stick figure and warm-yellow Border Collie. English-label port of `oil-visual`. (user)",
      "input": {
        "hint": "[explainer|cutout] <what the image must show>"
      },
      "name": "visual"
    },
    {
      "description": "Guide for writing idiomatic Rust code based on Apollo GraphQL's best practices handbook. Use this skill when: (1) writing new Rust code or functions, (2) reviewing or refactoring existing Rust code, (3) deciding between borrowing vs cloning or ownership patterns, (4) implementing error handling with Result types, (5) optimizing Rust code for performance, (6) writing tests or documentation for Rust projects. (project)",
      "name": "rust-best-practices"
    },
    {
      "description": "Comprehensively reviews SwiftUI code for best practices on modern APIs, maintainability, and performance. Use when reading, writing, or reviewing SwiftUI projects. (project)",
      "name": "swiftui-pro"
    },
    {
      "description": "Deep research harness — fan-out web searches, fetch sources, adversarially verify claims, synthesize a cited report. (dynamic workflow)",
      "name": "deep-research"
    },
    {
      "description": "(frontend-design) Guidance for distinctive, intentional visual design when building new UI or reshaping an existing one. Helps with aesthetic direction, typography, and making choices that don't read as templated defaults.",
      "name": "frontend-design:frontend-design"
    },
    {
      "description": "(swiftui-pro) Comprehensively reviews SwiftUI code for best practices on modern APIs, maintainability, and performance. Use when reading, writing, or reviewing SwiftUI projects.",
      "input": {
        "hint": "[focus area]"
      },
      "name": "swiftui-pro:swiftui-pro"
    },
    {
      "description": "Grant or revoke Claude agent access to your Design projects",
      "input": {
        "hint": "consent | revoke"
      },
      "name": "design"
    },
    {
      "description": "Push a React design system to claude.ai/design. This runs a converter that bundles the real component code (from Storybook or a bare package) and uploads it. Use when the user runs /design-sync or says \"sync my design system to Claude Design\".",
      "input": {
        "hint": "[<project hint, e.g. \"Acme DS\">]"
      },
      "name": "design-sync"
    },
    {
      "description": "Use this skill whenever you are about to create ANY chart, graph, plot, dashboard, or data visualization, in ANY output medium — an HTML or React artifact, inline SVG, plotting code in any library (matplotlib, plotly, d3, Recharts, …), an image/PNG you will render and upload, or a chart shared into Slack. Read it BEFORE writing the first line of chart code, choosing chart colors, building a stat tile / meter / KPI row, or laying out a dashboard. When the destination is a first-party document connector (host-designated, never self-described) that renders live charts, hand it the rows (inline, or as an uploaded data file the chart cites) rather than a rendered PNG/SVG — a picture of a chart loses hover, data inspection and per-value comments. Produces visualizations that read as one system — elegant, accessible, consistent in light and dark — using a brand-neutral placeholder palette you swap for your own. Teaches a design-system-agnostic method: a form heuristic, a color formula with a runnable validator, mark specs, and interaction rules. A validated default palette is documented in `references/palette.md` — swap that file's values for your brand's. Triggers on: \"chart\", \"graph\", \"plot\", \"data viz\", \"visualization\", \"dashboard\", \"analytics\", \"visualize data\", \"categorical colors\", \"sequential / diverging palette\", \"stat tile\", \"sparkline\", \"heatmap\", \"legend\", \"axis\", \"tooltip\", \"chart colors\", \"color by series\".",
      "name": "dataviz"
    },
    {
      "description": "Use this skill to configure the Claude Code harness via settings.json. Automated behaviors (\"from now on when X\", \"each time X\", \"whenever X\", \"before/after X\") require hooks configured in settings.json - the harness executes these, not Claude, so memory/preferences cannot fulfill them. Also use for: permissions (\"allow X\", \"add permission\", \"move permission to\"), env vars (\"set X=Y\"), hook troubleshooting, or any changes to settings.json/settings.local.json files. Examples: \"allow npm commands\", \"add bq permission to global settings\", \"move permission to user settings\", \"set DEBUG=true\", \"when claude stops show X\". For simple settings like theme/model, suggest the /config command.",
      "name": "update-config"
    },
    {
      "description": "Verify that a code change actually does what it's supposed to by exercising it end-to-end and observing behavior — drive the affected flow, not just tests or typecheck. Run before committing nontrivial changes; bootstraps this repo's project verify skill if none exists yet. Don't invoke it on a diff that only touches tests, docs, or other code with no runtime surface to drive (a change to product source always has one) — there's nothing to observe.",
      "name": "verify"
    },
    {
      "description": "Enable debug logging for this session and help diagnose issues",
      "input": {
        "hint": "[issue description]"
      },
      "name": "debug"
    },
    {
      "description": "Review the current diff, or a PR number/branch/path target, for correctness bugs (plus reuse/simplification/efficiency cleanups where the model's review recipe covers them) at the given effort level (low/medium: fewer, high-confidence findings; high→max: broader coverage, may include uncertain findings; ultra: deep multi-agent review in the cloud); with no level given, it reuses the level you typed last. Pass --comment to post findings as inline PR comments, or --fix to apply the findings to the working tree after the review. For ultra on a GitHub.com PR target, --post asks to post the finished review’s findings to the PR as a single comment from the user’s GitHub account (not a review; the launch dialog still confirms in interactive sessions, while non-interactive mode posts on the flag alone) and --no-post hides that option.",
      "input": {
        "hint": "[low|medium|high|xhigh|max|ultra] [--fix] [--comment] [<pr#>|<branch>|<path>]"
      },
      "name": "code-review"
    },
    {
      "description": "Review the changed code for reuse, simplification, efficiency, and altitude cleanups, then apply the fixes. Quality only — it does not hunt for bugs; use /code-review for that.",
      "input": {
        "hint": "[<target>]"
      },
      "name": "simplify"
    },
    {
      "description": "Research and plan a large-scale change, then execute it in parallel across 5–30 isolated worktree agents that each open a PR.",
      "input": {
        "hint": "<instruction>"
      },
      "name": "batch"
    },
    {
      "description": "Scan your transcripts for common read-only Bash and MCP tool calls, then add a prioritized allowlist to project .claude/settings.json to reduce permission prompts.",
      "name": "fewer-permission-prompts"
    },
    {
      "description": "Health-check the user's Claude Code setup and fix issues: diagnose installation health — what the `claude doctor` terminal diagnostics cover — from local data (duplicate or leftover installs, PATH, unparseable settings files, broken or colliding agent definitions, skills whose frontmatter fails to parse); find unused skills, MCP servers, and plugins versus their context cost and disable dead weight; deduplicate local CLAUDE.md files against checked-in ones; trim checked-in CLAUDE.md files by cutting content a session could derive from the codebase (directory layouts, tech-stack lists, architecture overviews) while keeping gotchas, rationale, and non-standard conventions; migrate always-loaded CLAUDE.md guidance into lazy skills and nested CLAUDE.md files; flag slow hooks and context-heavy extensions; check the installed version is current; make auto mode the default permission mode; and pre-approve frequently denied read-only commands. Use when the user asks for a doctor run, checkup, audit, tune-up, or cleanup of their Claude Code setup or configuration.",
      "name": "doctor"
    },
    {
      "description": "Run a prompt or slash command on a recurring interval (e.g. /loop 5m /foo). Omit the interval to let the model self-pace.",
      "input": {
        "hint": "[interval] [prompt]"
      },
      "name": "loop"
    },
    {
      "description": "Create, update, list, or run scheduled cloud agents (routines) that execute on a cron schedule.",
      "name": "schedule"
    },
    {
      "description": "Reference for the Claude API / Anthropic SDK — model ids, pricing, params, streaming, tool use, MCP, agents, caching, token counting, model migration.\nTRIGGER — read BEFORE opening the target file; don't skip because it \"looks like a one-liner\" — whenever: the prompt names Claude/Anthropic in any form (Claude, Anthropic, Fable, Opus, Sonnet, Haiku, `anthropic`, `@anthropic-ai`, `claude-*`, `us.anthropic.*`, `[1m]`); the user asks about an LLM (pricing/model choice/limits/caching) — never answer from memory; OR the task is LLM-shaped with provider unstated (agent/MCP/tool-definition/multi-agent/RAG/LLM-judge/computer-use; generate/summarize/extract/classify/rewrite/converse over NL; debugging refusals/cutoffs/streaming/tool-calls/tokens).\nSKIP only when another provider is being worked on (overrides all triggers): OpenAI/GPT/Gemini/Llama/Mistral/Cohere/Ollama named in the query; OR `grep -rE 'openai|langchain_openai|google.generativeai|genai|mistralai|cohere|ollama'` over the project hits (run this grep FIRST if no provider named — don't Read the file).",
      "name": "claude-api"
    },
    {
      "description": "Reference for writing a Workflow tool script (script API and gotchas, resume, quality patterns, worked examples). Load before authoring a script for a workflow the user already opted into; it does not itself authorize running one.",
      "name": "workflow-authoring"
    },
    {
      "description": "Launch and drive this project's app to see a change working. Use when asked to run, start, or screenshot the app, or to confirm a change works in the real app (not just tests). First looks for a project skill that already covers launching the app; otherwise falls back to built-in patterns per project type (CLI, server, TUI, Electron, browser-driven, library).",
      "name": "run"
    },
    {
      "description": "Author or improve the run-<unit> skill - a per-project skill that tells agents how to build, launch, and drive this project's app. Use when the user asks to set up the project, get it running, write run instructions, or verify build/run steps work from a clean environment.",
      "name": "run-skill-generator"
    },
    {
      "description": "Let Claude consult a stronger model at key moments",
      "input": {
        "hint": "[fable|opus|sonnet|off]"
      },
      "name": "advisor"
    },
    {
      "description": "(removed) Ask Claude to create/manage subagents, or edit .claude/agents/",
      "name": "agents"
    },
    {
      "description": "Teach auto mode about your environment, plus optional rule tweaks",
      "input": {
        "hint": "[--request-id <uuid>] (--wizard posture=… scope=… depth=… --propose | --expect-sha256 <64-hex> --apply-file <path>)"
      },
      "name": "auto-mode-setup"
    },
    {
      "description": "Configure the auto-compact window size",
      "input": {
        "hint": "[auto|<tokens>]"
      },
      "name": "autocompact"
    },
    {
      "description": "Set the prompt bar color for this session",
      "input": {
        "hint": "[red|blue|green|yellow|purple|orange|pink|cyan|default]"
      },
      "name": "color"
    },
    {
      "description": "Free up context by summarizing the conversation so far",
      "input": {
        "hint": "<optional custom summarization instructions>"
      },
      "name": "compact"
    },
    {
      "description": "Set a setting by key",
      "input": {
        "hint": "key=value"
      },
      "name": "config"
    },
    {
      "description": "List output styles or switch to one",
      "input": {
        "hint": "[style]"
      },
      "name": "output-style"
    },
    {
      "description": "Show current context usage",
      "name": "context"
    },
    {
      "description": "Set effort level for model usage",
      "input": {
        "hint": "<low|medium|high|xhigh|max|ultracode|auto>"
